#!/usr/bin/env node
"use strict";

// dock/index.html の style.css / app.js 参照を中身で置き換え、1 つの HTML にする。
// 使い方: node scripts/bundle-dock.js [--dock DIR] [--out FILE]
// 既定の出力: dist/obs-track-dock.html

const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");

function usage() {
  console.log(
    [
      "Usage: node scripts/bundle-dock.js [--dock DIR] [--out FILE]",
      "",
      "Inline dock/style.css and dock/app.js into dock/index.html.",
      "Default output: dist/obs-track-dock.html",
    ].join("\n"),
  );
}

function parseArgs(argv) {
  const opts = {
    dock: path.join(repoRoot, "dock"),
    out: path.join(repoRoot, "dist", "obs-track-dock.html"),
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      usage();
      process.exit(0);
    }
    if (arg !== "--dock" && arg !== "--out") {
      console.error(`unknown argument: ${arg}`);
      usage();
      process.exit(1);
    }
    const value = argv[++i];
    if (!value) {
      console.error(`missing value for ${arg}`);
      process.exit(1);
    }
    opts[arg.slice(2)] = path.resolve(value);
  }

  return opts;
}

function replaceOnce(source, pattern, replacer, label) {
  const flags = pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`;
  const found = source.match(new RegExp(pattern.source, flags)) || [];
  if (found.length !== 1) {
    throw new Error(`${label} が ${found.length} 件です。1 件だけ置き換えます。`);
  }
  return source.replace(pattern, replacer);
}

function main() {
  const opts = parseArgs(process.argv.slice(2));
  const html = fs.readFileSync(path.join(opts.dock, "index.html"), "utf8");
  const css = fs.readFileSync(path.join(opts.dock, "style.css"), "utf8");
  const js = fs.readFileSync(path.join(opts.dock, "app.js"), "utf8");

  let bundled = replaceOnce(
    html,
    /<link\b[^>]*\bhref=(["'])\.\/style\.css\1[^>]*>/i,
    () => `<style>\n${css.replace(/<\/style/gi, "<\\/style")}\n</style>`,
    "style.css の link",
  );

  bundled = replaceOnce(
    bundled,
    /<script\b([^>]*?)\bsrc=(["'])\.\/app\.js\2([^>]*)>\s*<\/script>/i,
    (_all, before, _quote, after) => {
      const attrs = `${before} ${after}`.replace(/\s+/g, " ").trim();
      const body = js.replace(/<\/script/gi, "<\\/script");
      return `<script${attrs ? ` ${attrs}` : ""}>\n${body}\n</script>`;
    },
    "app.js の script",
  );

  if (
    bundled.includes('href="./style.css"') ||
    bundled.includes("href='./style.css'") ||
    bundled.includes('src="./app.js"') ||
    bundled.includes("src='./app.js'")
  ) {
    throw new Error("外部の CSS / JS 参照が残っています");
  }

  const banner =
    "<!-- Generated by scripts/bundle-dock.js from dock/index.html, dock/style.css, and dock/app.js. -->";
  const nl = bundled.indexOf("\n");
  if (nl !== -1 && /^<!doctype html>/i.test(bundled)) {
    bundled = `${bundled.slice(0, nl)}\n${banner}\n${bundled.slice(nl + 1)}`;
  } else {
    bundled = `${banner}\n${bundled}`;
  }

  fs.mkdirSync(path.dirname(opts.out), { recursive: true });
  fs.writeFileSync(opts.out, bundled.endsWith("\n") ? bundled : `${bundled}\n`);
  console.log(opts.out);
}

try {
  main();
} catch (err) {
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}
